#define HOST(script, fn, arity) { #script "." #fn, arity }

// The host targets (gd::call_static): the GDScript functions the battle's ports
// call. Each is allowed only at the call site named here, none inside the
// fight's step loop. After each one the bridge reads everything again
// (PortBridge::call_static). Phase 1's eight, the battle ends, are ported
// (Phase 5 slice 09).
constexpr Host kHosts[] = {
	// collect_resource_node_result (battle_end_sites.cpp): a site's visit, at a
	// battle end, at most once a battle, when the guards of a dwelling the
	// player does not control or a field site's defenders are beaten.
	HOST(OverworldRules, _collect_resource_node_result, 5),
};

#undef HOST

// The battle port's table, listed in registry_tables.cpp.
Table battle_table() {
	return {"HEROES_NATIVE_BATTLE_LOG", kFunctions, sizeof(kFunctions) / sizeof(kFunctions[0]), kGdscriptOnly, sizeof(kGdscriptOnly) / sizeof(kGdscriptOnly[0]), kSharedMemos,
		sizeof(kSharedMemos) / sizeof(kSharedMemos[0]), kHosts, sizeof(kHosts) / sizeof(kHosts[0])};
}

